use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Create\InvitationCreateUsecase;

/**
 * HTTP driver controller that handles all HTML-rendered profile management pages.
 *
 * This class is the primary entry point for every browser-facing route under the
 * /oauth/openid/{tenant}/me path prefix.  It orchestrates the view, edit, password
 * change, MFA configuration, session listing / revocation, and user invitation flows
 * by delegating to the corresponding domain gateways and panel view components.
 *
 * Authentication is resolved from the tenant-scoped session cookie; unauthenticated
 * requests receive a 401 page with a link back to the authorization endpoint rather
 * than a redirect, so that the OAuth flow is not bypassed.
 *
 * All write operations wrap their gateway calls in an explicit SQL transaction via
 * SqlTemplate and handle rollback implicitly through SqlTemplate::close() in the
 * finally block.  Panels are panel view objects (ChangePasswordPanel, MfaPanel, etc.)
 * that produce raw HTML fragments which this controller wraps with the themed layout
 * provided by DecorateHtml.
 *
 * Translation is resolved from the Accept-Language request header unless the user's
 * stored profile locale overrides it, ensuring the UI is displayed in the user's
 * preferred language.
 */
class ProfileHtml
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly SqlTemplate $sql,
        private readonly SessionManager $sessions,
        private readonly ProfileGateway $gateway,
        private readonly PasswordGateway $passwordGateway,
        private readonly MfaGateway $mfaGateway,
        private readonly SessionsGateway $sessionsGateway,
        private readonly MessageProvider $messages,
        private readonly DecorateHtml $decorator,
        private readonly ProfileViewPanel $viewPanel,
        private readonly ProfileEditPanel $editPanel,
        private readonly ChangePasswordPanel $changePasswordPanel,
        private readonly MfaPanel $mfaPanel,
        private readonly SessionsPanel $sessionsPanel,
        private readonly InvitationCreateUsecase $inviteUsecase,
        private readonly TenantReadGateway $tenantGateway,
        private readonly UserReadGateway $userGateway,
        private readonly ClientStoreGateway $clientStore,
    ) {
    }

    /**
     * Handles GET requests to the profile overview page.
     *
     * Loads the session, fetches the stored OIDC profile, and renders the
     * ProfileViewPanel wrapped in the themed layout.  Redirects to the
     * unauthenticated page when no valid session is found.
     */
    public function view(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Profile view page");
        $span = $this->startSpan("Profile view page");
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $profile = $this->gateway->findByUser($session->userId);
            $translator = $this->translatorFor($request, $profile?->locale ?? '');
            $editUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/edit';
            $changePasswordUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/password';
            $mfaUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/mfa';
            $sessionsUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/sessions';
            $inviteUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/invite';
            $html = '<div class="section-card">' . $this->viewPanel->render(
                $profile,
                $editUrl,
                $changePasswordUrl,
                $mfaUrl,
                $sessionsUrl,
                $this->viewTexts($translator),
                $inviteUrl,
            ) . '</div>';
            $locale = $profile?->locale ?? '';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.view.title'), $html, $locale, 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles GET requests to the profile edit form page.
     *
     * Loads the current profile to pre-populate form fields and renders the
     * ProfileEditPanel.  Returns an unauthenticated page when no session is found.
     */
    public function edit(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Profile edit page");
        $span = $this->startSpan("Profile edit page");
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $profile = $this->gateway->findByUser($session->userId);
            $translator = $this->translatorFor($request, $profile?->locale ?? '');
            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/edit';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $html = '<div class="section-card">' . $this->editPanel->render($profile, $saveUrl, $cancelUrl, null, $this->editTexts($translator)) . '</div>';
            $locale = $profile?->locale ?? '';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.edit.title'), $html, $locale, 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles POST requests to persist profile edits.
     *
     * Parses the form body, persists the profile through ProfileGateway::save(), and
     * redirects to the view page on success.  Re-renders the edit form with an error
     * message and HTTP 422 on any gateway exception.
     */
    public function save(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Profile save");
        $span = $this->startSpan("Profile save");
        $tenant = $args['tenant'];
        $this->sql->begin();
        try {
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $data = $this->readData($request);
            $this->gateway->save($session->userId, $data);
            $this->sql->commit();
            $viewUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            return $response->withStatus(302)->withHeader('Location', $viewUrl);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $session = isset($session) ? $session : null;
            if ($session !== null) {
                $profile = $this->gateway->findByUser($session->userId);
                $translator = $this->translatorFor($request, $profile?->locale ?? '');
                $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/edit';
                $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
                $html = '<div class="section-card">' . $this->editPanel->render($profile, $saveUrl, $cancelUrl, $ex->getMessage(), $this->editTexts($translator)) . '</div>';
                $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.edit.title'), $html, '', 'full', $tenant));
                return $response->withStatus(422);
            }
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    /**
     * Handles GET requests to the user-invitation form page.
     *
     * Renders the invite form for the currently authenticated user.  Returns an
     * unauthenticated page when no valid session cookie is present.
     */
    public function invite(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $session = $this->loadSession($request, $tenant);
        if ($session === null) {
            return $this->renderUnauthenticated($request, $response, $tenant);
        }
        $translator = $this->translatorFor($request);
        $html = '<div class="section-card">' . $this->buildInviteForm($tenant, null, $translator) . '</div>';
        $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.invite.title'), $html, '', 'full', $tenant));
        return $response;
    }

    /**
     * Handles POST requests to submit a user invitation by email address.
     *
     * Creates the invitation record and dispatches the invitation email via
     * InvitationCreateUsecase.  Renders the form again with an error on validation
     * failure; shows a success confirmation on completion.
     */
    public function sendInvite(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $this->sql->begin();
        try {
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $body = (array) ($request->getParsedBody() ?? []);
            $email = trim((string) ($body['email'] ?? ''));
            $translator = $this->translatorFor($request);

            if ($email === '') {
                $this->sql->close();
                $html = '<div class="section-card">' . $this->buildInviteForm($tenant, $translator->get('profile.invite.email') . ' is required.', $translator) . '</div>';
                $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.invite.title'), $html, '', 'full', $tenant));
                return $response->withStatus(422);
            }

            $tenantEntity = $this->tenantGateway->findOneByDomain($tenant);
            if ($tenantEntity === null) {
                throw new \DomainException('Tenant not found.');
            }
            $tenantId = $tenantEntity->uid() ?? '';

            $inviter = $this->userGateway->findOneByUid($session->userId);
            $inviterEmail = $inviter?->getEmail() ?? '';

            $clientId    = $session->clientId;
            $redirectUri = $clientId !== '' ? ($this->clientStore->defaultRedirectUri($clientId) ?? '') : '';

            $params = new InvitationCreateParams(
                tenantName: $tenant,
                tenantId: $tenantId,
                email: $email,
                invitedByUserUid: $session->userId,
                invitedByEmail: $inviterEmail,
                baseUrl: $this->context->getBaseUrl(),
                clientId: $clientId,
                redirectUri: $redirectUri,
            );
            $this->inviteUsecase->create($params);
            $this->sql->commit();

            $backUrl = htmlspecialchars($this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me');
            $successMsg = htmlspecialchars($translator->get('profile.invite.success'));
            $backLabel = htmlspecialchars($translator->get('profile.invite.backToProfile'));
            $html = '<div class="section-card"><p class="success">' . $successMsg . '</p><p><a class="secondary-button" href="' . $backUrl . '">' . $backLabel . '</a></p></div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.invite.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (\DomainException $ex) {
            $translator = $this->translatorFor($request);
            $html = '<div class="section-card">' . $this->buildInviteForm($tenant, $ex->getMessage(), $translator) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.invite.title'), $html, '', 'full', $tenant));
            return $response->withStatus(422);
        } catch (Throwable $ex) {
            throw $ex;
        } finally {
            $this->sql->close();
        }
    }

    private function buildInviteForm(string $tenant, ?string $error, \Civi\Lughauth\Shared\Infrastructure\Translation\MessageCatalogue $t): string
    {
        $action = htmlspecialchars($this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/invite');
        $cancelUrl = htmlspecialchars($this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me');
        $errorHtml = $error !== null ? '<p class="error">' . htmlspecialchars($error) . '</p>' : '';
        return <<<HTML
            <h1>{$t->get('profile.invite.title')}</h1>
            <p>{$t->get('profile.invite.help')}</p>
            {$errorHtml}
            <form method="POST" action="{$action}">
                <label>{$t->get('profile.invite.email')}
                    <input type="email" name="email" required autocomplete="email" />
                </label>
                <input class="primary-button" type="submit" value="{$t->get('profile.invite.submit')}" />
                <a class="secondary-button" href="{$cancelUrl}">{$t->get('profile.invite.cancel')}</a>
            </form>
            HTML;
    }

    private function loadSession(ServerRequestInterface $request, string $tenant): ?\Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo
    {
        $cookies = $request->getCookieParams();
        $sessionId = $cookies['AUTH_SESSION_ID_' . strtoupper($tenant)] ?? null;
        if ($sessionId === null || $sessionId === '') {
            return null;
        }
        return $this->sessions->loadSession($sessionId, '', '');
    }

    private function renderUnauthenticated(ServerRequestInterface $request, ResponseInterface $response, string $tenant): ResponseInterface
    {
        $translator = $this->translatorFor($request);
        $loginUrl = htmlspecialchars($this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/authorize');
        $html = <<<HTML
            <h1>{$translator->get('profile.auth.title')}</h1>
            <p>{$translator->get('profile.auth.help')}</p>
            <p><a class="primary-button" href="{$loginUrl}">{$translator->get('profile.auth.login')}</a></p>
            HTML;
        $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.view.title'), '<div class="section-card">' . $html . '</div>', '', 'full', $tenant));
        return $response->withStatus(401);
    }

    /**
     * Handles GET requests to the change-password form page.
     *
     * Renders the ChangePasswordPanel inside the themed layout for the authenticated
     * user.  Returns an unauthenticated page when no session cookie is present.
     */
    public function changePassword(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Change password page");
        $span = $this->startSpan("Change password page");
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $translator = $this->translatorFor($request);
            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/password';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $html = '<div class="section-card">' . $this->changePasswordPanel->render($saveUrl, $cancelUrl, null, false, $this->passwordTexts($translator)) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.password.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles POST requests to persist a password change submitted via the profile form.
     *
     * Validates that new password and confirmation match before delegating to
     * PasswordGateway::changePassword().  Renders the form with a specific error message
     * for a wrong old password; throws for any unexpected error.
     */
    public function savePassword(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Save new password");
        $span = $this->startSpan("Save new password");
        $this->sql->begin();
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $body = (array) ($request->getParsedBody() ?? []);
            $currentPassword = (string) ($body['currentPassword'] ?? '');
            $newPassword = (string) ($body['newPassword'] ?? '');
            $confirmPassword = (string) ($body['confirmPassword'] ?? '');

            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/password';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $translator = $this->translatorFor($request);

            if ($newPassword !== $confirmPassword) {
                $this->sql->close();
                $html = '<div class="section-card">' . $this->changePasswordPanel->render($saveUrl, $cancelUrl, $translator->get('profile.password.errorMismatch'), false, $this->passwordTexts($translator)) . '</div>';
                $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.password.title'), $html, '', 'full', $tenant));
                return $response->withStatus(422);
            }

            $this->passwordGateway->changePassword($session->userId, $tenant, $currentPassword, $newPassword);
            $this->sql->commit();

            $html = '<div class="section-card">' . $this->changePasswordPanel->render($saveUrl, $cancelUrl, null, true, $this->passwordTexts($translator)) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.password.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (LoginException $ex) {
            $errorKey = $ex->auth->error ?? $ex->getMessage();
            $translator = $this->translatorFor($request);
            $error = $errorKey === 'wrong_old_pass' ? $translator->get('error.wrong_old_pass') : $translator->get('profile.password.errorGeneric');
            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $args['tenant'] . '/me/password';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $args['tenant'] . '/me';
            $html = '<div class="section-card">' . $this->changePasswordPanel->render($saveUrl, $cancelUrl, $error, false, $this->passwordTexts($translator)) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.password.title'), $html, '', 'full', $args['tenant']));
            return $response->withStatus(422);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    /**
     * Handles GET requests to the MFA configuration page.
     *
     * Reads the current MFA enablement state and, when disabled, generates a fresh
     * setup payload to render in the MfaPanel.  Returns an unauthenticated page when
     * no session is found.
     */
    public function mfa(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("MFA page");
        $span = $this->startSpan("MFA page");
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $translator = $this->translatorFor($request);
            $enabled = $this->mfaGateway->isEnabled($session->userId, $tenant);
            $setup = $enabled ? null : $this->mfaGateway->buildSetup($session->userId, $tenant);
            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/mfa';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $html = '<div class="section-card">' . $this->mfaPanel->render($enabled, $saveUrl, $cancelUrl, $setup, null, false, $this->mfaTexts($translator)) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.mfa.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles POST requests to enable or disable MFA for the authenticated user.
     *
     * Reads the "action" field from the form body to determine whether to call
     * MfaGateway::disable() or MfaGateway::enable().  Re-renders the MFA panel with
     * an error message on gateway failure; shows a success state on completion.
     */
    public function saveMfa(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Save MFA settings");
        $span = $this->startSpan("Save MFA settings");
        $tenant = $args['tenant'];
        $this->sql->begin();
        try {
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $translator = $this->translatorFor($request);
            $body = (array) ($request->getParsedBody() ?? []);
            $action = (string) ($body['action'] ?? '');
            if ($action === 'disable') {
                $this->mfaGateway->disable($session->userId, $tenant);
            } else {
                $seed = (string) ($body['seed'] ?? '');
                $otp = (string) ($body['otp'] ?? '');
                $this->mfaGateway->enable($session->userId, $tenant, $seed, $otp);
            }
            $this->sql->commit();
            $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/mfa';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $enabled = $this->mfaGateway->isEnabled($session->userId, $tenant);
            $setup = $enabled ? null : $this->mfaGateway->buildSetup($session->userId, $tenant);
            $html = '<div class="section-card">' . $this->mfaPanel->render($enabled, $saveUrl, $cancelUrl, $setup, null, true, $this->mfaTexts($translator)) . '</div>';
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.mfa.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            $session = isset($session) ? $session : null;
            if ($session !== null) {
                $translator = $this->translatorFor($request);
                $saveUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/mfa';
                $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
                $enabled = $this->mfaGateway->isEnabled($session->userId, $tenant);
                $setup = $enabled ? null : $this->mfaGateway->buildSetup($session->userId, $tenant);
                $html = '<div class="section-card">' . $this->mfaPanel->render($enabled, $saveUrl, $cancelUrl, $setup, $ex->getMessage(), false, $this->mfaTexts($translator)) . '</div>';
                $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.mfa.title'), $html, '', 'full', $tenant));
                return $response->withStatus(422);
            }
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    /**
     * Handles GET requests to the active sessions listing page.
     *
     * Fetches all non-expired sessions for the authenticated user and renders them
     * through SessionsPanel, highlighting the current session by cookie ID.
     */
    public function sessions(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Sessions page");
        $span = $this->startSpan("Sessions page");
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $translator = $this->translatorFor($request);
            $sessions = $this->sessionsGateway->listByUser($session->userId);
            $revokeBaseUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/sessions/revoke';
            $cancelUrl = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me';
            $currentSessionId = $this->currentSessionId($request, $tenant);
            $html = $this->sessionsPanel->render($sessions, $revokeBaseUrl, $cancelUrl, $currentSessionId, $this->sessionsTexts($translator));
            $response->getBody()->write($this->decorator->getFullPage($request, $translator->get('profile.sessions.title'), $html, '', 'full', $tenant));
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Handles POST requests to revoke a specific session owned by the authenticated user.
     *
     * Verifies that the target session belongs to the current user and is not the
     * current session before delegating to SessionsGateway::revoke().  Redirects back
     * to the sessions listing page on completion.
     */
    public function revokeSession(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Revoke session");
        $span = $this->startSpan("Revoke session");
        $this->sql->begin();
        try {
            $tenant = $args['tenant'];
            $session = $this->loadSession($request, $tenant);
            if ($session === null) {
                return $this->renderUnauthenticated($request, $response, $tenant);
            }
            $sessionId = (string) ($args['sessionId'] ?? '');
            $currentSessionId = $this->currentSessionId($request, $tenant);
            $sessions = $this->sessionsGateway->listByUser($session->userId);
            $owned = false;
            foreach ($sessions as $activeSession) {
                if ($activeSession->sessionId === $sessionId) {
                    $owned = true;
                    break;
                }
            }
            if ($owned && $sessionId !== '' && $sessionId !== $currentSessionId) {
                $this->sessionsGateway->revoke($sessionId);
            }
            $this->sql->commit();
            $url = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant . '/me/sessions';
            return $response->withStatus(302)->withHeader('Location', $url);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readData(ServerRequestInterface $request): OidcProfileData
    {
        $parsed = $request->getParsedBody() ?? [];
        $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
        return new OidcProfileData(
            givenName: isset($body['givenName']) ? (string) $body['givenName'] : null,
            familyName: isset($body['familyName']) ? (string) $body['familyName'] : null,
            middleName: isset($body['middleName']) ? (string) $body['middleName'] : null,
            nickname: isset($body['nickname']) ? (string) $body['nickname'] : null,
            preferredUsername: isset($body['preferredUsername']) ? (string) $body['preferredUsername'] : null,
            pictureUrl: isset($body['pictureUrl']) ? (string) $body['pictureUrl'] : null,
            websiteUrl: isset($body['websiteUrl']) ? (string) $body['websiteUrl'] : null,
            gender: isset($body['gender']) ? (string) $body['gender'] : null,
            birthdate: isset($body['birthdate']) ? (string) $body['birthdate'] : null,
            zoneinfo: isset($body['zoneinfo']) ? (string) $body['zoneinfo'] : null,
            locale: isset($body['locale']) ? (string) $body['locale'] : null,
            phoneNumber: isset($body['phoneNumber']) ? (string) $body['phoneNumber'] : null,
            phoneNumberVerified: null,
            addressJson: null,
        );
    }

    private function translatorFor(ServerRequestInterface $request, string $profileLocale = ''): MessageCatalogue
    {
        $locale = $profileLocale !== '' ? $profileLocale : $this->resolveLocale($request);
        return $this->messages->messages('forms', $locale, __DIR__ . '/../Translations');
    }

    private function resolveLocale(ServerRequestInterface $request): string
    {
        $header = $request->getHeaderLine('Accept-Language');
        if ($header === '') {
            return '';
        }
        $first = trim(explode(',', $header)[0] ?? '');
        return strtolower(trim(explode(';', $first)[0] ?? ''));
    }

    private function currentSessionId(ServerRequestInterface $request, string $tenant): ?string
    {
        $cookies = $request->getCookieParams();
        $sessionId = $cookies['AUTH_SESSION_ID_' . strtoupper($tenant)] ?? null;
        if (!is_string($sessionId) || $sessionId === '') {
            return null;
        }
        return $sessionId;
    }

